import json

# Try showing actual intersection values as-is
test_lines = test_grid  
bg_value = 9
h_out, w_out = 3, 3
marker_rows = [4, 11, 18, 25]
marker_cols = [1, 6, 11, 16, 21]

output_grid = []
for rz in range(h_out):
    r_start = int(rz / h_out * len(test_lines))
    r_end = int((rz + 1) / h_out * len(test_lines))
    row_vals = []
    for cz in range(w_out):
        c_start = int(cz / w_out * len(test_lines[0]))
        c_end = int((cz + 1) / w_out * len(test_lines[0]))

        # Find what value is at marker intersections in this zone
        found_values = set()
        for r in marker_rows:
            for c in marker_cols:
                if r_start <= r < r_end and c_start <= c < c_end:
                    found_values.add(test_lines[r][c])

        if found_values:
            # Multiple intersections? Use most common or first
            from collections import Counter
            vals_in_zone = []
            for r in marker_rows:
                for c in marker_cols:
                    if r_start <= r < r_end and c_start <= c < c_end:
                        vals_in_zone.append(test_lines[r][c])
            val = Counter(vals_in_zone).most_common(1)[0][0]
        else:
            val = bg_value

        row_vals.append(val)
    output_grid.append(row_vals)

print("Output (actual intersection values):")
for row in output_grid:
    print(row)

final_json = {"action": "submit", "grid": output_grid}
print(f"\n=== SUBMITTING ===")
print(json.dumps(final_json))

